SPOTS = [
    # ---------- 上海 ----------
    ("豫园", "上海市", "上海", 31.227, 121.492, "名胜", "全年", ["名胜", "亲子"],
     "始建于明嘉靖年间的江南古典园林，有四百余年历史，取「豫悦老亲」之意得名。园内玉玲珑为江南三大名石之一，亭台楼阁、曲径回廊在不到三十亩的方寸间移步换景。出园即入城隍庙商圈，南翔小笼包与五香豆香气四溢，元宵灯会更是沪上盛事。与外滩、南京路步行街构成上海经典一日游线。"),
    ("上海科技馆", "上海市", "上海", 31.225, 121.545, "亲子", "全年", ["亲子", "城市"],
     "以「自然、人、科技」为主题的大型科普场馆，设有生物万象、地壳探秘、智慧之光等十余个常设展区，IMAX 科学影城与球幕影院体验震撼。机器人世界、彩虹乐园深受亲子家庭喜爱，展品互动性强，孩子可以玩上一整天。地铁二号线上海科技馆站直达，与世纪公园相邻，是浦东亲子游的核心站点。"),
    ("朱家角古镇", "上海市", "上海", 31.110, 121.050, "城市", "全年", ["城市", "名胜"],
     "上海保存最完整的江南水乡古镇，位于青浦淀山湖畔，有「上海威尼斯」之称。漕港河穿镇而过，放生桥为沪上最大五孔石拱桥，北大街老店铺鳞次栉比，阿婆粽、扎肉香气弥漫。相比周庄乌镇，这里更生活化，早上喝茶的本地老人与摇橹船构成一幅闲适画卷。十七号线直达，是上海人周末「微度假」首选。"),
    # ---------- 江苏 ----------
    ("夫子庙-秦淮风光带", "江苏省", "南京", 32.020, 118.790, "名胜", "全年", ["名胜", "城市"],
     "「烟笼寒水月笼纱，夜泊秦淮近酒家」。以夫子庙古建筑群为中心、十里秦淮为轴线，是中国第一个开放式 5A 景区。江南贡院见证了科举千年兴衰，乌衣巷口夕阳斜照王谢风流，乘画舫夜游秦淮灯彩如昼。鸭血粉丝汤、蟹黄汤包等金陵小吃在这条街上应有尽有，春节灯会人山人海，平日傍晚最见韵味。"),
    ("周庄古镇", "江苏省", "苏州", 31.115, 120.845, "城市", "全年", ["城市", "名胜"],
     "「上有天堂，下有苏杭，中间有个周庄」。这座九百余岁的江南水乡古镇因陈逸飞油画《故乡的回忆》名扬海外，双桥、沈厅、张厅是必访三景，万三蹄的香味从明初飘到今天。小桥流水人家在这里是日常而非布景，坐一条摇橹船穿桥洞而过，才懂什么叫「中国第一水乡」。建议住一晚，清晨与夜色的周庄最温柔。"),
    ("同里古镇", "江苏省", "苏州", 31.160, 120.710, "城市", "全年", ["城市", "名胜"],
     "江南六大古镇之一，旧称「富土」，五湖环抱，家家临水、户户通舟。镇内的退思园是江南古镇中唯一的世界文化遗产，取「退而思过」之意，贴水而建精巧雅致；三桥（太平、吉利、长庆）走一遍是本地人的成人礼习俗。相比周庄的商业化，同里更安静本色，评弹声里喝一杯阿婆茶，时间都慢了下来。"),
    ("鼋头渚", "江苏省", "无锡", 31.520, 120.240, "自然", "3-4月", ["自然", "名胜"],
     "太湖第一名胜，郭沫若赞「太湖佳绝处，毕竟在鼋头」。半岛形如巨鼋伸入太湖，长春桥、赏樱楼一线是中华第一赏樱胜地——三月底四月初三万余株樱花与太湖碧波相映，落樱如雨。登鹿顶山可俯瞰太湖七十二峰，仙岛（三山）需乘船前往。除樱花季外，夏日荷风、秋日渔帆、冬日雪景各有味道，建议安排半天到一天。"),
    ("灵山大佛", "江苏省", "无锡", 31.425, 120.090, "名胜", "全年", ["名胜", "亲子"],
     "世界最高大的露天青铜释迦牟尼立像之一，通高 88 米，1997 年建成开光。大佛右手指天称「施无畏印」，九龙灌浴表演每日定时开启，莲花绽放、太子佛像旋转升起，配乐喷泉蔚为壮观；梵宫以华藏塔风格建成，内部廊柱穹顶金碧辉煌如进入佛国。拈花湾小镇相邻，夜宿一晚禅意满满。无锡高铁站转车约 40 分钟。"),
    ("花果山", "江苏省", "连云港", 34.690, 119.330, "自然", "全年", ["自然", "亲子"],
     "《西游记》里美猴王的老家，主峰玉女峰为江苏最高峰（624.4 米）。山中七十二洞、水帘洞与神话原型呼应，野生猕猴成群出没极有灵性，阿育王塔、三元宫古建筑群千年香火不绝。登山步道与索道结合，山顶远眺黄海烟波浩渺。连云港市区车程约 30 分钟，花果山风鹅与海鲜是当地的味觉名片，亲子游尤其合适。"),
    ("天目湖", "江苏省", "常州", 31.320, 119.410, "自然", "全年", ["自然", "亲子"],
     "常州溧阳的碧水明珠，因属天目山余脉得名，湖水清澈如镜，群山环抱率真幽静。山水园可乘游船登龙兴岛，彩蝶谷与蝴蝶馆孩子最喜欢；南山竹海万亩翠竹连绵，乘地面缆车登吴越弟一峰，熊猫馆里的国宝憨态可掬。天目湖砂锅鱼头汤白如奶，是此行必尝的招牌美味。溧阳高铁站转车约 20 分钟，适合周末两日游。"),
    ("溱湖国家湿地公园", "江苏省", "泰州", 32.480, 120.120, "自然", "全年", ["自然", "亲子"],
     "长江文化与黄河文化交汇的里下河湿地，以「水、湿地、生态」为内涵，麋鹿与丹顶鹤在此栖息——溱湖簖蟹更是一绝。乘摇橹船穿行芦苇迷宫，水道九曲十八弯，风过处绿浪翻滚；每年清明二天极其热闹的溱潼会船节号称「天下会船数溱潼」。姜堰区车程 20 分钟，湿地科普馆与亲子探险乐园配套成熟。"),
    ("沙家浜", "江苏省", "苏州", 31.660, 120.800, "自然", "全年", ["自然", "名胜"],
     "因京剧《沙家浜》名闻天下的水乡湿地，芦苇荡一望无际，是当年新四军养伤抗战的根据地。坐手摇船钻进芦苇迷宫，感受「芦荡火种」的传奇；横泾老街影视基地还原了阿庆嫂的春来茶馆。国防教育园与湿地科普馆寓教于游，大闸蟹季节前来，一壶黄酒配蟹正是江南秋味。常熟市区车程约 20 分钟。"),
    ("茅山", "江苏省", "常州", 31.720, 119.400, "名胜", "全年", ["名胜", "自然"],
     "道教上清派祖庭，有「第一福地，第八洞天」之称，横跨常州金坛与镇江句容。主峰大茅峰海拔 372.5 米，九霄万福宫雄踞山巅，喜客泉击掌即涌泉相报的奇观令人称奇。抗战时期是新四军根据地，苏南抗战胜利纪念碑下燃放爆竹能听到「军号声」，堪称世界声学奇观。登山与研学两相宜，道教文化与红色记忆在此交汇。"),
    ("瘦西湖", "江苏省", "扬州", 32.420, 119.420, "名胜", "3-5月", ["名胜", "自然"],
     "「两堤花柳全依水，一路楼台直到山」。瘦西湖由隋唐以来历代的护城河疏浚而成，因湖身清瘦狭长得名。五亭桥如莲花绽放，白塔晴云、二十四桥明月夜的典故俯拾皆是，「烟花三月下扬州」的最好打开方式就是沿湖漫步或乘画舫。清明前后琼花与柳絮齐飞，是扬州最美的时节；个园、何园、东关街可组成扬州两日。"),
    ("环球恐龙城", "江苏省", "常州", 31.820, 119.970, "亲子", "全年", ["亲子", "城市"],
     "以中华恐龙园为核心的综合性主题度假区，恐龙馆收藏陈列全国极为丰富的恐龙化石，中华恐龙馆外观如三条巨龙盘旋。疯狂火龙钻、水火动力等游乐项目刺激缤纷，恐龙谷温泉泡汤解乏，迪诺水镇夜晚灯光如童话城堡。适合亲子家庭安排一到两天，常州北站车程 15 分钟，配套酒店餐饮一应俱全。"),
    ("无锡影视基地", "江苏省", "无锡", 31.500, 120.270, "名胜", "全年", ["名胜", "亲子"],
     "中央电视台在太湖之滨建造的影视拍摄基地，三国城、水浒城依山傍水而建，规模宏大。每天定时的《三英战吕布》马战表演、火烧赤壁水战特技还原名著场景，演员阵容专业，观众可以骑马、乘古战船过一把穿越瘾。与鼋头渚隔湖相望，可组合游览；亲子家庭与三国迷尤其尽兴，半天到一天即可。"),
    ("吴中太湖旅游区", "江苏省", "苏州", 31.200, 120.400, "自然", "全年", ["自然", "名胜"],
     "苏州吴中区环太湖景区的统称，涵盖太湖山水与吴文化精华：穹窿山为苏州第一高山，孙武曾在此隐居著兵法；旺山茶园竹林环抱，是苏州人私藏的村落；东山雕花楼雕刻精美绝伦，启园御码头康熙曾登岸。太湖三白（白鱼、白虾、银鱼）是餐桌必点。建议自驾环湖，春采枇杷、秋吃蟹，四季皆有滋味。"),
    # ---------- 浙江 ----------
    ("乌镇", "浙江省", "嘉兴", 30.748, 120.490, "城市", "全年", ["城市", "名胜"],
     "「来过，便不曾离开」。乌镇是江南水乡保护的典范，东栅浓缩了传统水乡风情，西栅由古建修复而来，夜色里灯光与水影交织成网，是公认最美的水乡夜景。这里是茅盾故里、世界互联网大会永久会址，古韵与科技在此奇妙共存。乌篷船、染坊、皮影戏值得细品，住西栅景区内民宿才能拥有清晨与深夜的乌镇。"),
    ("西塘古镇", "浙江省", "嘉兴", 30.945, 120.885, "城市", "全年", ["城市", "名胜"],
     "「生活着的千年古镇」，嘉善县境内的江南六大古镇之一。最动人的是绵延近千米的烟雨长廊——雨天不湿鞋、盛夏不撑伞，廊棚下摇扇喝茶的慢生活延续了几百年。石皮弄窄得只容一人通过，送子来凤桥上凭栏看摇橹船来来往往。夜里的西塘酒吧与灯笼倒映水中，白天与黑夜是两个古镇。嘉善南站打车 20 分钟即达。"),
    ("雁荡山", "浙江省", "温州", 28.370, 121.070, "自然", "全年", ["自然"],
     "「海上名山，寰中绝胜」，因山顶有湖、秋雁栖宿得名，是东南亚大陆东缘出露最完整的白垩纪流纹岩地质博物馆，世界地质公园。灵峰日夜景判若两山——合掌峰白天是双掌合十，夜晚化作相依恋人；灵岩飞渡表演惊险绝伦；大龙湫瀑布落差 197 米，单级落差全国之最。温州乐清市车程 1 小时，建议两天游三灵。"),
    ("横店影视城", "浙江省", "金华", 29.140, 120.300, "名胜", "全年", ["名胜", "亲子"],
     "「中国好莱坞」，全球规模最大的影视实景拍摄基地，秦王宫的恢弘、清明上河图的市井、明清宫苑的威严、广州街香港街的怀旧，十几座跨越千年的影视城在此集结。每天上演数百场演艺秀，运气好还能偶遇剧组明星。在横店住两三天，白天穿行片场，晚上看《梦幻太极》火山爆发实景秀，像活在一部戏里。"),
    ("南浔古镇", "浙江省", "湖州", 30.870, 120.250, "城市", "全年", ["城市", "名胜"],
     "江南六大古镇中最低调的富庶之地，明清时期以蚕丝贸易富可敌国，「四象八牛七十二金黄狗」的巨贾传说至今流传。小莲庄的十亩荷塘、嘉业堂藏书楼的万卷藏书、张石铭旧宅的法式洋楼，中西合璧的建筑水准冠绝江南。商业气息最淡、生活气息最浓，百间楼的清晨炊烟是水乡该有的模样。"),
    ("神仙居", "浙江省", "台州", 28.660, 120.580, "自然", "全年", ["自然"],
     "「神仙居住的地方」，台州仙居的国家公园式景区，一山一水皆有仙气。西罨寺冰川遗迹形成的巨大石峰群鬼斧神工，观音岩、如意桥、南天桥悬于云海之上，飞鹰道与悬空栈道步步惊心。云雾缭绕时群峰若隐若现，如水墨长卷徐徐展开。索道上下省力，环线徒步约 4 小时；与皤滩古镇可组成一日游，仙居杨梅季（6 月）前来更甜。"),
    ("天台山", "浙江省", "台州", 29.150, 121.030, "自然", "全年", ["自然", "名胜"],
     "佛教天台宗发祥地、济公活佛故里，徐霞客游记的开篇之地。国清讲寺始建于隋代，千年隋梅岁岁开花，寺前稻田梵音袅袅不收门票的清修氛围全国罕见；石梁飞瀑为天下第一奇观，花岗岩天然石梁横跨瀑布之上；华顶国家森林公园云锦杜鹃五月花开成海。天台县城食宿方便，素斋是一绝。"),
    ("江郎山-廿八都", "浙江省", "衢州", 28.530, 118.580, "自然", "全年", ["自然", "名胜"],
     "江郎山以三爿石奇观闻名——三块高逾 300 米的丹霞石柱拔地擎天，是「中国丹霞」世界自然遗产的核心区之一，郎峰一线天宽仅 3.5 米、高 312 米，为全国之最。一小时车程外的廿八都古镇藏在仙霞岭深山，方言腔调竟有十三种，徽式、浙式、闽式、欧式建筑同居一街，是遗落大山里的百姓古镇。"),
    ("西溪国家湿地公园", "浙江省", "杭州", 30.270, 120.060, "自然", "全年", ["自然", "城市"],
     "中国首个国家湿地公园，与西湖、西泠并称杭州「三西」，电影《非诚勿扰》取景地。「一曲溪流一曲烟」，乘摇橹船深入水域纵横的芦苇荡，白鹭掠水而过，城市边缘竟有如此野趣。秋芦飞雪（11-12 月）与端午龙舟是两大看点，福堤绿堤免费开放，深潭口古樟树下便是《非诚勿扰》的相亲亭。地铁三号线可达。"),
    ("根宫佛国", "浙江省", "衢州", 29.130, 118.380, "名胜", "全年", ["名胜", "亲子"],
     "开化根雕艺术与佛文化的世界级殿堂，徐谷青大师以根雕再现了释迦牟尼、五百罗汉等庞大造像群，最大的根雕佛国大殿由巨型香樟根单体制成，重达 40 余吨。醉根天工博物馆的藏品让人惊叹「化腐朽为神奇」的匠艺，童趣园的动物根雕憨态可掬。开化青蛳与清水鱼是当地美食名片，衢州高铁站转车约 1 小时。"),
    ("嘉兴南湖", "浙江省", "嘉兴", 30.740, 120.760, "名胜", "全年", ["名胜"],
     "与南京玄武湖、杭州西湖并称江南三大名湖，更因湖心岛上一艘画舫载入史册——1921 年中共一大在此完成最后议程，红船成为精神象征。湖面烟雨迷蒙时最有意境，烟雨楼始建于五代，乾隆六下江南八次登临。湖滨可步行环湖，乘船登湖心岛瞻仰红船，月河历史街区的小吃与花鸟市场就在附近。"),
    ("缙云仙都", "浙江省", "丽水", 28.660, 120.100, "自然", "全年", ["自然", "名胜"],
     "「黄山之奇、华山之险、桂林之秀」集于一身，鼎湖峰拔地而起 170.8 米，如春笋破土直刺云天，是世界上最高的单体石柱之一。朱潭山老农牵牛过石桥的画面是《中国国家地理》级别的经典，黄帝祠宇是南方轩辕黄帝祭祀中心。九曲练溪、十里画廊，乘竹筏漂流的视角最美。缙云西站车程 15 分钟，烧饼一定要尝。"),
    ("绍兴鲁迅故里-沈园", "浙江省", "绍兴", 30.000, 120.590, "名胜", "全年", ["名胜", "城市"],
     "鲁迅笔下世界的实景原乡：三味书屋里还能找到少年鲁迅刻下的「早」字，百草园的皂荚树与泥墙根仍在原处，咸亨酒店门口的孔乙己铜像手茴香豆。一墙之隔的沈园，因陆游与唐琬的《钗头凤》成为千古爱情圣地。乌篷船摇过八字桥，黄酒配臭豆腐，绍兴的气质是越读越有味的。景区免费需预约，黄酒棒冰是夏日顶流。"),
    # ---------- 安徽 ----------
    ("宏村", "安徽省", "黄山", 30.000, 117.990, "名胜", "全年", ["名胜", "城市"],
     "「中国画里的乡村」，2000 年与西递共同列入世界文化遗产。始建于南宋的牛形村落，雷岗山为牛首、月沼为牛胃、南湖为牛肚，人工水系穿堂入户九百年不涝，是古代水利智慧的活教材。月沼倒影与南湖画桥是写生者的天堂，《卧虎藏龙》取景地。清晨炊烟与深秋红叶的宏村最动人，住一晚才不辜负它的晨昏。"),
    ("西递", "安徽省", "黄山", 29.990, 117.950, "名胜", "全年", ["名胜", "城市"],
     "与宏村齐名的世界文化遗产古村落，因村边有溪、村中原有「递铺」机构得名。明清民居 224 幢保存完好，胡文光刺史牌楼是村口地标，「桃花源里人家」的布局如船形。木雕、石雕、砖雕三雕艺术在追慕堂与履福堂里登峰造极，楹联家训透着徽商的处世哲学。比宏村更安静，适合慢慢逛上半天，徽菜毛豆腐必尝。"),
    ("九华山", "安徽省", "池州", 30.480, 117.800, "名胜", "全年", ["名胜"],
     "地藏菩萨道场，中国佛教四大名山之一，素有「莲花佛国」之称，99 座山峰形似莲花。99.9 米高的地藏菩萨圣像为世界最大地藏像，肉身宝殿供奉千年不腐的肉身菩萨，百岁宫内的明代无瑕禅师真身令人惊叹。天台峰云海与佛光时有出现，花台栈道春看杜鹃冬赏雾凇。池州高铁站转车约 1 小时，礼佛加观光建议两天。"),
    ("天柱山", "安徽省", "安庆", 30.720, 116.450, "自然", "全年", ["自然", "名胜"],
     "「一柱擎天」的江淮第一山，主峰天柱峰海拔 1489.8 米，如巨柱擎天故名，为世界地质公园。花岗岩峰林与神秘谷（皖公神府）的迷宫洞穴是精华，炼丹湖海拔 1100 米，为国内第三大高山平湖，湖光山色恍如天境。这里还是黄梅戏之乡，孔雀东南飞的故事发生在近旁。潜山高铁站转车约 20 分钟，索道上下一天可玩精华。"),
    ("天堂寨", "安徽省", "六安", 31.170, 115.760, "自然", "全年", ["自然", "亲子"],
     "大别山第二高峰，「华东最后一片原始森林」，横跨皖鄂两省的天堂寨是江淮分水岭。瀑布群是最大亮点——九影瀑、泻玉瀑等大小瀑布上百道，夏季水量最丰时如银河倾泻；白马大峡谷栈道沿溪而上清凉宜人，登顶可一脚跨两省看云海日出。森林覆盖率达 96.5%，负氧离子爆表，是避暑洗肺胜地。金寨站转车约 1 小时。"),
    ("绩溪龙川", "安徽省", "宣城", 30.070, 118.600, "名胜", "全年", ["名胜"],
     "胡锦涛故里的千年古村落，「木雕艺术殿堂」胡氏宗祠供奉着胡氏先祖，奕世尚书坊为明代石雕精品，水街两岸徽派民居倒映如画。村落形如龙舟出海，登最高处俯瞰全貌更觉玄妙。绩溪是徽菜发源地，一品锅与臭鳜鱼的味道在这里最正宗。可与徽杭古道徒步、鄣山大峡谷组合成两日徽文化之旅。"),
    ("三河古镇", "安徽省", "合肥", 31.510, 117.230, "城市", "全年", ["城市", "名胜"],
     "有 2500 多年历史的江淮水乡古镇，丰乐河、杭埠河、小南河三水交汇得名，古称「鹊渚」。杨振宁旧居、孙立人故居等名人宅邸散落古镇，望月阁、万年台古韵悠悠，一人巷的窄巷回忆着刘同兴隆庄的商贾往事。米饺、茶干与三河米酒是舌尖记忆。合肥市区车程 40 分钟，免费开放，夜色中的水乡灯光秀值得一看。"),
    # ---------- 福建 ----------
    ("福建土楼（永定·南靖）", "福建省", "龙岩", 24.680, 116.970, "名胜", "全年", ["名胜", "亲子"],
     "「天上掉下的飞碟，地下冒出的蘑菇」。土楼是世界独一无二的山区大型夯土民居，2008 年列入世界文化遗产：承启楼「土楼王」四环相套、鼎盛时住 800 余人，振成楼中西合璧如一顶乌纱帽，怀远楼工艺最为精美。客家人聚族而居的智慧——防风抗震、聚族御敌——全写在夯土墙里。永定与南靖土楼群相距不远，建议各住一晚。"),
    ("太姥山", "福建省", "宁德", 27.160, 120.200, "自然", "全年", ["自然"],
     "「海上仙都」，太姥山立于东海之滨，峰林怪石在云雾中若隐若现。夫妻峰相依相偎的轮廓是它的标志，一线天窄处仅容一人侧身通过，九鲤朝天、一片瓦、通天洞步步是景。山中寺庙尼庵众多，摩霄峰观日台看东海日出气势磅礴。福鼎市中心车程 30 分钟，福鼎白茶的产地就在山脚下，游山品茶两不误。"),
    ("白水洋-鸳鸯溪", "福建省", "宁德", 26.980, 119.020, "自然", "夏季", ["自然", "亲子"],
     "「天下绝景，白水洋」——八万平方米的平坦岩石河床一石而就，水恰没过脚踝，阳光下水波如银，是世界上唯一的「浅水广场」，夏天赤脚戏水的天然乐园。相邻的鸳鸯溪是国家一级保护动物鸳鸯越冬地，每年秋季上千对鸳鸯飞来过冬，凌云栈道悬于峡谷，百丈漈水帘洞瀑布从天而降。屏南县车程 30 分钟，带好水鞋与换洗衣物。"),
    ("泰宁风景旅游区", "福建省", "三明", 26.900, 117.170, "自然", "全年", ["自然"],
     "「水上丹霞」的杰作，泰宁是世界自然遗产「中国丹霞」的重要组成部分、世界地质公园。大金湖碧水丹山，乘船游湖两岸赤壁丹崖倒映水中；上清溪竹筏漂流九十九曲、八十八滩；寨下大峡谷被联合国专家称为「世界地质公园的榜样景区」；尚书第明代官宅建筑群保存完好。泰宁县城食宿便利，两天可游遍精华。"),
    ("三坊七巷", "福建省", "福州", 26.080, 119.300, "城市", "全年", ["城市", "名胜"],
     "「中国城市里坊制度活化石」与「明清建筑博物馆」，三坊（衣锦坊、文儒坊、光禄坊）七巷（杨桥巷、郎官巷、塔巷、黄巷、安民巷、宫巷、吉庇巷）自晋唐延续至今。林则徐、严复、冰心、林觉民等众多名人从这里走向历史舞台，一座坊半部中国近代史。鱼丸、肉燕、荔枝肉在坊巷间飘香，晚上灯光亮起更见古韵。"),
    ("湄洲岛", "福建省", "莆田", 25.050, 119.100, "名胜", "全年", ["名胜", "自然"],
     "妈祖的诞生地，全球 3 亿多妈祖信众的「麦加」，妈祖祖庙香火千年不绝。岛上妈祖文化园的巨型妈祖石雕像面海而立，鹅尾神石园的海蚀地貌奇观鬼斧神工，黄金沙滩细软绵长。农历三月廿三妈祖诞辰的庙会盛况空前，来自世界各地的进香团络绎不绝。莆田文甲码头乘轮渡 15 分钟上岛，环岛电瓶车串联各景点。"),
    ("古田旅游区", "福建省", "龙岩", 25.230, 116.810, "名胜", "全年", ["名胜"],
     "红色圣地古田会议会址所在地，「古田会议永放光芒」八个大字在会址后山的油菜花田前熠熠生辉。1929 年古田会议确立了思想建党、政治建军的原则，会址原为廖氏宗祠，建筑古朴庄重。周边的五龙村客家风情浓郁，红军小镇可体验穿红军服、吃红军饭。龙岩/上杭车程约 1 小时，是红色研学与客家文化之旅的核心站点。"),
    ("清源山", "福建省", "泉州", 24.930, 118.600, "名胜", "全年", ["名胜", "自然"],
     "泉州的母亲山，「北有武夷，南有清源」。山中老君岩是中国现存最大的道教石雕老君造像，慈眉善目历经千年风霜；弘一法师舍利塔静立山间，「悲欣交集」的人生注解令人动容。天湖泛舟、南台岩远眺泉州湾，少林禅寺的南少林武术表演值得一看。泉州古城世遗之旅可与清源山组合，山下面线糊配油条是地道早餐。"),
    # ---------- 江西 ----------
    ("庐山", "江西省", "九江", 29.560, 115.980, "自然", "全年", ["自然", "名胜"],
     "「匡庐奇秀甲天下」，世界文化景观遗产。苏轼「不识庐山真面目」、李白「飞流直下三千尺」都为它代言——三叠泉瀑布落差 155 米须亲攀方见其壮丽；牯岭镇云中山城繁华如市，如琴湖、花径、美庐别墅与庐山会议旧址串起半部近代史。夏季平均气温 22℃ 是长江中下游避暑首选，含鄱口日出与五老峰云海最不容错过。"),
    ("井冈山", "江西省", "吉安", 26.580, 114.170, "名胜", "全年", ["名胜", "自然"],
     "「中国革命的摇篮」，第一个农村革命根据地在此创建，星星之火由此燎原。黄洋界哨口云海翻涌时如临仙境，当年黄洋界保卫战的炮声仿佛犹在耳畔；茨坪革命旧址群、井冈山革命博物馆系统呈现两年零四个月的峥嵘岁月。如今森林覆盖率 86%，杜鹃山十里杜鹃长廊春天如霞似火。红色研学与自然观光在此完美结合。"),
    ("滕王阁", "江西省", "南昌", 28.680, 115.880, "名胜", "全年", ["名胜", "城市"],
     "「落霞与孤鹜齐飞，秋水共长天一色」——王勃一篇《滕王阁序》让这座江南三大名楼之首名垂千古。始建于唐永徽四年，历史上 29 次毁建，今阁为 1989 年重建，高 57.5 米仿宋式雄踞赣江之滨。登阁远眺赣江烟波与八一大桥，夜幕降临华灯初上时最是壮观。南昌拌粉配瓦罐汤的早餐仪式感，别忘了体验。"),
    ("婺源江湾", "江西省", "上饶", 29.330, 118.060, "城市", "3-4月", ["城市", "名胜"],
     "婺源是「中国最美乡村」的核心县，江湾古镇为 5A 龙头：萧江宗祠气势恢宏，江永纪念馆纪念着这位写《河洛精蕴》的清代经学家。婺源真正的精华在春——篁岭晒秋、江岭万亩梯田油菜花海、李坑汪口的徽派村落沿溪而列。建议自驾或包车串游，三天时间把「书乡」「茶乡」的味道慢慢品出来，荷包红鲤鱼必尝。"),
    ("龙虎山", "江西省", "鹰潭", 28.080, 117.070, "自然", "全年", ["自然", "名胜"],
     "道教正一派祖庭，「丹成而龙虎现」得名，世界自然遗产、世界地质公园。泸溪河畔丹霞地貌如赤城千仞，乘竹筏顺流而下，两岸仙岩之上悬棺群千年未解——升棺表演还原古越崖墓之谜。天师府、上清宫是历代天师起居之所，象鼻山栈道观景极佳。鹰潭站车程 20 分钟，正一天师道的符箓文化值得深入了解。"),
    ("龟峰", "江西省", "上饶", 28.230, 117.430, "自然", "全年", ["自然"],
     "「江上龟峰天下稀」，世界自然遗产「中国丹霞」的组成部分，因山体如巨型石龟而得名。骆驼峰、老人峰、三叠龟等丹霞石峰造型逼真到不可思议，龟峰天然卧佛全长 416 米为世界最大天然山体卧佛。登好汉坡俯瞰碧水丹山，清水湖上泛舟看龟峰倒影。弋阳县车程 15 分钟，与三清山组合成上饶丹霞之旅。"),
    ("明月山", "江西省", "宜春", 27.900, 114.230, "自然", "全年", ["自然", "亲子"],
     "「明月处处有，宜春月最明」，明月山因「月」文化得名，是嫦娥奔月传说的发源地之一。青云栈道悬于崖壁环绕云谷，云谷飞瀑落差 119 米为江南第一高瀑；高山观光小火车连接明月山与羊狮慕，穿越云端的体验独特。山下温汤镇富硒温泉闻名千年，登山归来泡汤解乏是标准动线。宜春站车程 15 分钟。"),
    ("瑞金共和国摇篮", "江西省", "赣州", 25.890, 116.030, "名胜", "全年", ["名胜"],
     "「红色故都」，1931 年中华苏维埃共和国临时中央政府在此成立，共和国从瑞金走来。叶坪的革命旧址群古樟环绕，红军广场的红军烈士纪念塔如一枚子弹直指苍穹；沙洲坝的红井旁立着「吃水不忘挖井人」的石碑，二苏大的中华苏维埃共和国临时中央政府大礼堂造型如一顶红军八角帽。是系统了解中华苏维埃历史的必访之地。"),
    ("大觉山", "江西省", "抚州", 27.700, 117.150, "自然", "夏季", ["自然", "亲子"],
     "「神山圣水，觉者天堂」，资溪县的大觉山以原始森林与峡谷漂流闻名。大觉岩寺建于天然岩洞之中，千年古刹禅意悠远；大觉者峰海拔 1118 米如大佛端坐。亚洲第一漂的大觉山漂流全程 3.6 公里、落差 188 米，激流回旋惊险刺激，夏季日均游客爆满。资溪是「面包之乡」，山脚下的小面包香甜可口。"),
    ("武功山", "江西省", "萍乡", 27.480, 114.230, "自然", "全年", ["自然"],
     "「云中草原，户外天堂」，武功山的高山草甸绵延十万亩，是同纬度地区罕见的草原奇观。金顶白鹤峰海拔 1918.3 米，云海、日出、星空帐篷节是户外爱好者的朝圣理由；徒步全程穿越（龙山村-发云界-金顶）两天一夜，是华东最经典的徒步线路之一。索道三段式可轻松登顶看日落云海。萍乡北站有景区直通车。"),
    # ---------- 山东 ----------
    ("趵突泉", "山东省", "济南", 36.660, 117.020, "名胜", "全年", ["名胜", "城市"],
     "「天下第一泉」，济南七十二名泉之首，乾隆南巡时尝此泉水泡茶封为御泉。三窟并发、水涌若轮的奇观已延续千年，泉池中锦鲤成群，「趵突腾空」在丰水期最为壮观。公园内李清照纪念堂值得拜谒，漱玉泉相传为她漱玉洗笔之处。泉水泡茶试一下「泉水大碗茶」，与周边黑虎泉、五龙潭组成泉城一日游。"),
    ("崂山", "山东省", "青岛", 36.150, 120.620, "自然", "全年", ["自然", "名胜"],
     "「海上第一名山」，中国海岸线上海拔最高的山峰（1132.7 米），山海相连的独特景观全国唯一。崂山是道教名山，太清宫的蒲松龄写《聊斋》时曾在此居住，穿墙术的故事就发生在这里。仰口湾沙滩、巨峰云海、北九水十八潭各有洞天，崂山可乐与矿泉水名声在外。青岛市区地铁可达，晴天看山海相拥最出片。"),
    ("刘公岛", "山东省", "威海", 37.510, 122.190, "名胜", "全年", ["名胜", "亲子"],
     "「不沉的战舰」，威海湾中的这座小岛是北洋海军的诞生地与甲午海战的终章之地。中国甲午战争博物院以大量史料与定远舰残骸遗物讲述那段悲壮历史，历史选择展馆发人深省。岛上森林覆盖率达 87%，旗顶山炮台、水师学堂建筑群保存完好。威海旅游码头乘船 20 分钟上岛，是爱国主义教育与海岛风光兼得的行程。"),
    ("龙口南山", "山东省", "烟台", 37.620, 120.530, "名胜", "全年", ["名胜", "亲子"],
     "「福如东海，寿比南山」的实景版。世界最大的锡青铜坐佛——南山大佛高 38.66 米端坐山间，药师玉佛殿玉石莹润；南山禅寺、香水庵古刹群香火绵延，中华历史传承园再现五千年文明长卷。宗教文化与游乐设施（水上乐园、滑草场）兼具，适合家庭组合出游。龙口市车程 20 分钟，烟台机场 1 小时。"),
    ("台儿庄古城", "山东省", "枣庄", 34.560, 117.730, "城市", "全年", ["城市", "名胜"],
     "「天下第一庄」，京杭大运河中心点上的古城，抗战史上台儿庄大捷的战场。古城重建后汇集了八种建筑风格与七十二座庙宇，江北水乡与大战故地双重身份，夜里的摇橹船与灯火是「活着的古运河」最佳注脚。大战纪念馆记录了 1938 年那场惨烈的胜利。住古城内民宿，夜晚的酒吧与灯火值得慢慢逛。"),
    ("曲阜三孔", "山东省", "济宁", 35.600, 117.000, "名胜", "全年", ["名胜", "亲子"],
     "孔子故里的孔庙、孔府、孔林合称「三孔」，1994 年列入世界文化遗产。孔庙是祭祀孔子的庙堂，奎文阁藏历代御赐书籍，十三碑亭矗立唐宋至清御碑；孔府为「天下第一家」，衍圣公世袭近九百年；孔林是世界上延时最久、规模最大的家族墓地，古柏森森。晨光中开城仪式不可错过，研学游的顶级目的地。"),
    ("黄河口生态旅游区", "山东省", "东营", 37.760, 119.050, "自然", "秋季", ["自然", "亲子"],
     "黄河入海的地方——「黄蓝交汇」的奇观是母亲河奔赴大海的终章，乘船入海可见河海相接的泾渭分明。新生湿地广袤无垠，芦花如雪的季节（10-11 月）铺天盖地，东方白鹳与丹顶鹤在候鸟季云集。红地毯（翅碱蓬）把滩涂染成绯红。东营市区车程 1 小时，生态研学与摄影创作的宝藏地。"),
    ("青州古城", "山东省", "潍坊", 36.690, 118.480, "城市", "全年", ["城市", "名胜"],
     "古九州之一的青州有 7000 余年文明史，古城内有全国唯一的县级一级博物馆——青州博物馆的龙兴寺佛教造像震惊世界。偶园古街店铺林立，隆盛糕点的蜜三刀是百年老味道，归来堂与李清照纪念祠藏在古街深处。古城免费开放，夜色中的鼓楼与城墙灯光秀有味道。青州市北站车程 15 分钟。"),
    ("微山湖", "山东省", "济宁", 34.730, 117.300, "自然", "全年", ["自然", "亲子"],
     "「西边的太阳就要落山了，微山湖上静悄悄」——铁道游击队的故乡，中国北方最大的淡水湖。十万亩荷花（7-8 月）铺满湖面，微山湖湿地红荷旅游区的荷景最为壮观；乘船登南阳古镇，运河穿镇而过的老街市井气息浓厚。湖产四鼻孔鲤鱼、乌鳢与鸭蛋是地道湖味。济宁/滕州车程 1 小时内。"),
    ("威海华夏城", "山东省", "威海", 37.400, 122.180, "名胜", "全年", ["名胜", "亲子"],
     "在矿坑废墟上重建的生态奇迹，历时十余年修复 44 处矿坑，建成集东方古典园林与文化演艺于一体的 5A 景区。夏园的胶东民俗、禹王宫的大禹治水故事值得细品，王牌演出《神游传奇》秀以山体为幕、水陆空立体呈现，震撼程度在国内演艺秀中名列前茅。与刘公岛组合成威海两日游，暑期亲子尤其合适。"),
    ("沂蒙山", "山东省", "临沂", 35.750, 118.100, "自然", "全年", ["自然", "名胜"],
     "「人人那个都说哎，沂蒙山好」——革命老区的红色热土，也是山水秀美的生态宝地。云蒙景区的森林尖索道、龟蒙景区的鹰窝峰挂壁栈道与高达 218 米的巨型山体雕刻「蒙山寿星」各有看点。孟良崮战役纪念馆记录了 1947 年那场关键战役。煎饼卷大葱与光棍鸡是沂蒙味道的代表。"),
]
